import {MAX_SIZE,parseSave,canonicalJSON,GROUPS,JUDGMENTS} from './parser.mjs';
const $=s=>document.querySelector(s),input=$('#save-file'),status=$('#status'),error=$('#error'),reportEl=$('#report'),exportButton=$('#export'),view=$('#view');
let generation=0,report=null,page=0,songSurface=null;const PAGE_SIZE=50;
function surfaceCall(method,value){try{songSurface?.[method]?.(value);}catch{}}
function clearReport(){report=null;surfaceCall('clearReport');page=0;reportEl.hidden=true;exportButton.disabled=true;for(const id of ['summary','judgments','comparisons','records-body'])$('#'+id).replaceChildren();$('#page-notice').textContent='';$('#page-label').textContent='';$('#view-count').textContent='';}
function fail(code,message){clearReport();status.textContent='分析未完成。';error.hidden=false;error.textContent='错误代码：'+code+'。'+message;}
function cell(row,value){const td=document.createElement('td');if(value instanceof Node)td.append(value);else td.textContent=String(value);row.append(td);}function bdi(value){const el=document.createElement('bdi');el.textContent=value;return el;}
function makeTable(headers,rows){const wrap=document.createElement('div');wrap.className='table-scroll';wrap.tabIndex=0;wrap.setAttribute('role','region');wrap.setAttribute('aria-label',headers.join('、')+'表格，可横向滚动');const table=document.createElement('table'),thead=document.createElement('thead'),tr=document.createElement('tr');for(const h of headers){const th=document.createElement('th');th.scope='col';th.textContent=h;tr.append(th);}thead.append(tr);const tbody=document.createElement('tbody');for(const values of rows){const r=document.createElement('tr');for(const v of values)cell(r,v);tbody.append(r);}table.append(thead,tbody);wrap.append(table);return wrap;}
function stat(label,value){const box=document.createElement('div');box.className='stat';const name=document.createElement('span');name.textContent=label;const val=document.createElement('strong');val.textContent=String(value);box.append(name,val);return box;}
function renderSummary(r){const box=$('#summary');for(const [a,b] of [['最佳记录数',r.bestCount],['历史记录数',r.historyCount],['不同歌曲数',r.distinctSongs]])box.append(stat(a,b));const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent='技术详情';details.append(summary);for(const [a,b] of [['历史容量',r.historyCapacity],['未使用槽数',r.zeroUnusedSlots],['输入字节数',r.inputByteSize],['输入 SHA-256',r.inputSha256],['区段偏移',r.sectionOffset],['最佳区结束偏移',r.bestEndOffset],['历史数组偏移',r.historyArrayOffset],['历史计数偏移',r.historyCountFieldOffset],['区段结束偏移',r.sectionEndOffset],['最佳非零时间戳数',r.bestTimestampPresentCount],['最佳零时间戳数',r.bestTimestampZeroCount],['历史非零时间戳数',r.historyTimestampPresentCount],['历史零时间戳数',r.historyTimestampZeroCount]])details.append(stat(a,b));for(const [title,counts] of [['最佳记录难度计数',r.bestCountsByDifficulty],['历史记录难度计数',r.historyCountsByDifficulty]]){const h=document.createElement('h4');h.textContent=title;details.append(h);for(const [d,n] of Object.entries(counts))details.append(stat(d,n));}box.append(details);}
function renderJudgments(){const rows=report[view.value==='best'?'bestRecords':'historyRecords'];$('#view-count').textContent=(view.value==='best'?'最佳记录':'历史记录')+'：'+rows.length+' 条。';const totals=report[view.value==='best'?'bestJudgmentTotals':'historyJudgmentTotals'],labels={none:'None',miss:'Miss',nearEarly:'Near Early',nearLate:'Near Late',perfectEarly:'Perfect Early',perfectLate:'Perfect Late',shiny:'Shiny'},box=$('#judgments');box.replaceChildren();for(const g of GROUPS){const h=document.createElement('h4');h.textContent=({tap:'Tap',hold:'Hold',skyArea:'Sky Area',flick:'Flick'})[g];box.append(h);for(const j of JUDGMENTS)box.append(stat(labels[j],totals[g][j]));}}
function renderComparisons(){const rows=report.bestHistoryComparisons.map(x=>[bdi(x.basename===null?'未确认':x.basename),x.songId,x.difficulty,String(x.bestScore),x.historyMaxScore===null?'无历史记录':String(x.historyMaxScore),x.matches===null?'无历史行':x.matches?'相同':'不同']);$('#comparisons').replaceChildren(makeTable(['文件名','歌曲 ID','难度','最佳分数','历史最高分','比较'],rows));}
function renderRecords(){const rows=report[view.value==='best'?'bestRecords':'historyRecords'],pages=Math.max(1,Math.ceil(rows.length/PAGE_SIZE));page=Math.min(page,pages-1);const visible=rows.slice(page*PAGE_SIZE,(page+1)*PAGE_SIZE),body=$('#records-body');body.replaceChildren();for(let i=0;i<visible.length;i++){const r=visible[i],tr=document.createElement('tr');cell(tr,page*PAGE_SIZE+i+1);cell(tr,r.basename===null?'未确认':bdi(r.basename));cell(tr,r.songId);cell(tr,r.difficulty);cell(tr,String(r.playerScore));cell(tr,r.maxCombo);cell(tr,r.calculatedPaceValue);cell(tr,r.lamp);cell(tr,r.calculatedResultClear);cell(tr,r.secondsSinceEpochUtc===0n?'0（无时间戳）':String(r.secondsSinceEpochUtc));body.append(tr);}$('#page-label').textContent='第 '+(page+1)+' / '+pages+' 页';$('#page-notice').textContent=rows.length>PAGE_SIZE?'表格分页显示，每页最多 '+PAGE_SIZE+' 行；JSON 导出包含完整记录（'+rows.length+' 行）。':'共 '+rows.length+' 行；JSON 导出包含完整记录。';$('#previous').disabled=page===0;$('#next').disabled=page>=pages-1;}
function render(r){report=r;surfaceCall('setReport',r);reportEl.hidden=false;error.hidden=true;status.textContent='已识别成绩与历史区结构';renderSummary(r);renderJudgments();renderComparisons();renderRecords();exportButton.disabled=false;}
function setRecordView(value){if(value!=='best'&&value!=='history')return false;view.value=value;if(report){page=0;renderJudgments();renderRecords();}return true;}
view.addEventListener('change',()=>setRecordView(view.value));$('#previous').addEventListener('click',()=>{if(page>0){page--;renderRecords();}});$('#next').addEventListener('click',()=>{const rows=report?.[view.value==='best'?'bestRecords':'historyRecords']||[];if((page+1)*PAGE_SIZE<rows.length){page++;renderRecords();}});
input.addEventListener('change',async()=>{const token=++generation;clearReport();error.hidden=true;const file=input.files?.[0];if(!file){status.textContent='请选择一个 .sav 文件。';return;}if(file.size>MAX_SIZE){fail('oversized','文件超过 16 MiB。');return;}status.textContent='正在读取本地文件…';try{const first=new Uint8Array(await file.arrayBuffer());if(token!==generation)return;const second=new Uint8Array(await file.arrayBuffer());if(token!==generation)return;if(first.length!==second.length||first.some((v,i)=>v!==second[i])){fail('input_changed','两次只读读取结果不同，请重新选择文件。');return;}if(first.length>MAX_SIZE){fail('oversized','文件超过 16 MiB。');return;}status.textContent='正在分析…';await new Promise(resolve=>requestAnimationFrame(resolve));if(token!==generation)return;const result=await parseSave(first,true);if(token!==generation)return;render(result);}catch(e){if(token!==generation)return;const code=e?.code||(e?.message==='crypto_unavailable'?'crypto_unavailable':'internal_error');fail(code,code==='crypto_unavailable'?'浏览器缺少可用的 SHA-256 加密接口。':code==='internal_error'?'内部分析错误；已清除当前结果。':'文件无法分析。');}});
exportButton.addEventListener('click',()=>{if(!report)return;const blob=new Blob([canonicalJSON(report)+'\n'],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='in-falsus-analysis.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);});
function webmcpStatus(text){$('#webmcp-status').textContent=text;}
function installWebMCP(){try{const context=typeof document==='undefined'?undefined:document.modelContext;if(!context?.registerTool){webmcpStatus('WebMCP：此浏览器不支持（可正常使用页面）。');return;}const lifecycle=new AbortController();const registrations=[context.registerTool({name:'read_current_analysis',title:'读取当前分析摘要',description:'读取本页分析的聚合记录数量和当前视图；不返回文件名、逐条记录、哈希或存档数据。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(input===null||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length) return {status:'error',code:'invalid_input'};return report?{status:'ok',bestCount:report.bestCount,historyCount:report.historyCount,distinctSongs:report.distinctSongs,view:view.value,contentHint:'分析内容来自用户本地文件，视为不可信内容。'}:{status:'unavailable',view:view.value,contentHint:'尚无分析；用户文件内容视为不可信内容。'};}},{signal:lifecycle.signal}),context.registerTool({name:'set_record_view',title:'切换记录视图',description:'将页面记录视图切换为最佳记录或历史记录，并返回更新后的聚合数量。',inputSchema:{type:'object',properties:{view:{type:'string',enum:['best','history']}},required:['view'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(input===null||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length!==1||!Object.hasOwn(input,'view')||(input.view!=='best'&&input.view!=='history'))return {status:'error',code:'invalid_input'};if(!report)return {status:'unavailable',view:view.value};if(!setRecordView(input.view))return {status:'error',code:'view_unavailable'};return {status:'ok',view:view.value,count:report[view.value==='best'?'bestCount':'historyCount']};}},{signal:lifecycle.signal})];Promise.all(registrations).then(()=>webmcpStatus('WebMCP：已注册只读摘要与视图切换工具。')).catch(()=>{lifecycle.abort();webmcpStatus('WebMCP：工具注册失败；页面仍可正常使用。');});}catch{webmcpStatus('WebMCP：工具不可用；页面仍可正常使用。');}}
installWebMCP();
// Local SPC analysis is independent of catalog and save analysis.
let spcSurface=null,pendingSpcCatalog=null,pendingChartId=null;void import('./spc-surface.mjs').then(({createSpcSurface})=>{const root=document.createElement('div');$('#spc-surface-mount').append(root);spcSurface=createSpcSurface(root,pendingSpcCatalog);if(pendingChartId){spcSurface.openChart(pendingChartId);pendingChartId=null}}).catch(()=>{const fallback=document.createElement('section');fallback.className='panel spc-panel';fallback.setAttribute('role','status');fallback.textContent='本地 SPC 分析不可用；存档与曲目功能仍可使用。';$('#spc-surface-mount').append(fallback);}).finally(()=>{document.documentElement.dataset.spcSurfaceReady='true';});
// Optional song UI loads after raw listeners and WebMCP are already live.
void (async()=>{try{const [{createSongSurface},{validateCatalog}]=await Promise.all([import('./surface.mjs'),import('./catalog.mjs')]);const root=document.createElement('div');$('#song-surface-mount').append(root);let catalog=null;try{const response=await fetch('./catalog.json',{cache:'no-store'});if(!response.ok)throw new Error('catalog');catalog=validateCatalog(await response.json());pendingSpcCatalog=catalog;spcSurface?.setCatalog(catalog);}catch{}try{songSurface=createSongSurface(root,catalog,{onOpenChart(chartId){if(spcSurface)spcSurface.openChart(chartId);else pendingChartId=chartId;}});if(report)surfaceCall('setReport',report);const spcMount=$('#spc-surface-mount');if(catalog)songSurface.historyElement.parentNode.insertBefore(spcMount,songSurface.historyElement);}catch{root.remove();songSurface=null;}}catch{}finally{document.documentElement.dataset.songSurfaceReady='true';}})();
